INSERT INTO "forcador_linhas" ("id", "fabricante_id", "nome", "versao_catalogo", "ativo_comercial", "observacao_versao", "linha_anterior_id", "descricao_comercial", "imagem_path", "id_comercial") VALUES (5, 1, 'EDH - 6 Aletas', '04/2025', TRUE, NULL, NULL, 'Evaporador com dupla saída de ar com 6 aletas por polegada e baixo nível de ruído para aplicações como sala de preparo, câmaras frigoríficas, corredores de recebimento de produtos e laboratórios. Características: Dreno metálico, bandeja articulável e laterais removíveis, suporte de fixação, tubo com plug de borracha pressurizado 30 psi e grade metálica.', '/uploads/d9e0a42b32b34007860c55648bdd8bc3.png', '4.2.1.2');
